/* Parse & Validate the OpenAI-compatible request.
   Outputs either {ok:true, ...} for the happy path or
   {__error:true, status, openai_error} which the error branch turns into
   an OpenAI-format HTTP error response.

   Auth model (since priority 3):
   - primary key: $env.CHAT_API_KEY (shared with LobeChat's OPENAI_API_KEY)
     -> unlimited, logged as key_name 'primary'
   - managed keys: SHA-256(provided) looked up in Data Table `gateway_keys`
     (columns: key_hash, name, enabled, rate_limit_rpm, total_cost)
   - per-key rate limit: chat_executions rows with the same key_name created
     within the last 60s vs rate_limit_rpm (0 = unlimited). Fail-open on
     counting errors — availability over strictness on a personal platform. */
const req = $input.first().json;
const body = req.body || {};
const headers = req.headers || {};
const startedAt = Date.now();

const error = (status, code, message, type) => [{ json: { __error: true, status, openai_error: { error: { message, type: type || 'invalid_request_error', code } } } }];
const authError = (message) => [{ json: { __error: true, status: 401, openai_error: { error: { message, type: 'authentication_error', code: 'invalid_api_key' } } } }];

// --- public API helpers (same pattern as the retention workflow) ---
const base = 'http://localhost:5678/api/v1';
const api = (method, path, qs, payload) => this.helpers.httpRequest({
  method,
  url: base + path,
  headers: { 'X-N8N-API-KEY': $env.N8N_API_KEY },
  qs,
  body: payload,
});

const provided = String(headers.authorization || '').replace(/^Bearer\s+/i, '');
const primaryKey = $env.CHAT_API_KEY;
if (!primaryKey) {
  return error(500, 'server_misconfigured', 'CHAT_API_KEY is not configured on the n8n instance');
}

let keyName = null;
let keyHash = null;
let rateLimitRpm = 0;

if (provided === primaryKey) {
  keyName = 'primary';
} else if (!provided) {
  return authError('Missing API key. Provide it via the Authorization: Bearer <key> header.');
} else {
  // managed key: hash it and look it up in the gateway_keys table
  let hash;
  try {
    hash = require('crypto').createHash('sha256').update(provided).digest('hex');
  } catch (e) {
    return error(500, 'server_misconfigured', 'crypto module unavailable on this n8n instance (set NODE_FUNCTION_ALLOW_BUILTIN=crypto)');
  }
  let tables;
  try {
    tables = await api('GET', '/data-tables', { limit: 100 });
  } catch (e) {
    return error(500, 'key_lookup_failed', 'Failed to query data tables: ' + String(e && e.message ? e.message : e));
  }
  const byName = {};
  for (const t of tables.data || []) byName[t.name] = t.id;
  const gt = byName['gateway_keys'];
  if (!gt) {
    return error(500, 'server_misconfigured', 'gateway_keys data table is missing (run n8n/scripts/deploy.mjs)');
  }
  let rows;
  try {
    rows = await api('GET', '/data-tables/' + gt + '/rows', {
      limit: 1,
      filter: JSON.stringify({ type: 'and', filters: [
        { columnName: 'key_hash', condition: 'eq', value: hash },
        { columnName: 'enabled', condition: 'eq', value: 1 },
      ] }),
    });
  } catch (e) {
    return error(500, 'key_lookup_failed', 'Failed to query gateway_keys: ' + String(e && e.message ? e.message : e));
  }
  const key = (rows.data || [])[0];
  if (!key) {
    return authError('Invalid API key. Provide it via the Authorization: Bearer <key> header.');
  }
  keyName = String(key.name || 'unnamed');
  keyHash = hash;
  rateLimitRpm = Number(key.rate_limit_rpm || 0);

  // per-key rate limit: rolling 60s window. NOTE: counting happens in code
  // (fetch newest rows, parse createdAt) because SQL date filters compare
  // stored strings and ISO values inconsistently across formats.
  if (rateLimitRpm > 0 && byName['chat_executions']) {
    let recent;
    try {
      recent = await api('GET', '/data-tables/' + byName['chat_executions'] + '/rows', {
        limit: 250,
        sortBy: 'createdAt:desc',
        filter: JSON.stringify({ type: 'and', filters: [
          { columnName: 'key_name', condition: 'eq', value: keyName },
        ] }),
      });
      const cutoff = Date.now() - 60000;
      let used = 0;
      for (const row of recent.data || []) {
        const t = Date.parse(row.createdAt || '');
        if (Number.isFinite(t) && t >= cutoff) used++;
        else break; // rows arrive newest-first
      }
      if (used >= rateLimitRpm) {
        return error(429, 'rate_limit_exceeded', 'Rate limit reached for key "' + keyName + '": ' + rateLimitRpm + ' requests/min. Retry shortly.', 'rate_limit_error');
      }
    } catch (e) {
      // fail open — see header comment
    }
  }

  // per-key budget hard limits (rolling counters maintained by the success log; 0 = unlimited)
  const budgetDaily = Number(key.budget_daily_usd || 0);
  const budgetMonthly = Number(key.budget_monthly_usd || 0);
  if (budgetDaily > 0 || budgetMonthly > 0) {
    const nowChk = Date.now();
    const rb = (x) => Math.round(x * 1e6) / 1e6;
    const eff24 = (nowChk - (Date.parse(key.spend_24h_at || '') || 0)) <= 24 * 3600 * 1000 ? Number(key.spend_24h || 0) : 0;
    const eff30 = (nowChk - (Date.parse(key.spend_30d_at || '') || 0)) <= 30 * 24 * 3600 * 1000 ? Number(key.spend_30d || 0) : 0;
    if (budgetDaily > 0 && eff24 >= budgetDaily) {
      return error(429, 'insufficient_quota', 'Budget exceeded for key "' + keyName + '": rolling 24h spend ' + rb(eff24) + ' USD >= limit ' + rb(budgetDaily) + ' USD. Adjust the budget or wait for the window to roll.', 'insufficient_quota');
    }
    if (budgetMonthly > 0 && eff30 >= budgetMonthly) {
      return error(429, 'insufficient_quota', 'Budget exceeded for key "' + keyName + '": rolling 30d spend ' + rb(eff30) + ' USD >= limit ' + rb(budgetMonthly) + ' USD. Adjust the budget or wait for the window to roll.', 'insufficient_quota');
    }
  }
}

// --- model routing: alias -> upstream model + whether tools are armed ---
const MODEL_ALIASES = {
  'deepseek-agent': { upstream: 'deepseek-chat', tools: true },
  'deepseek-chat': { upstream: 'deepseek-chat', tools: false },
  'deepseek-reasoner': { upstream: 'deepseek-reasoner', tools: false },
  'deepseek-v4-flash': { upstream: 'deepseek-v4-flash', tools: true },
};
const DEFAULT_MODEL = 'deepseek-agent';

const model = body.model || DEFAULT_MODEL;
const alias = MODEL_ALIASES[model];
if (!alias) {
  return error(404, 'model_not_found', `The model '${model}' does not exist. Available: ${Object.keys(MODEL_ALIASES).join(', ')}`);
}
const upstreamModel = alias.upstream;

// --- messages ---
const rawMessages = body.messages;
if (!Array.isArray(rawMessages) || rawMessages.length === 0) {
  return error(400, 'missing_messages', "'messages' must be a non-empty array");
}
const flatten = (content) => {
  if (typeof content === 'string') return content;
  if (Array.isArray(content)) return content.map((p) => p.text || '').join('\n');
  return JSON.stringify(content);
};
const messages = rawMessages
  .filter((m) => m && typeof m.role === 'string')
  .map((m) => ({ role: m.role, content: flatten(m.content) }));
const lastUser = [...messages].reverse().find((m) => m.role === 'user');
if (!lastUser) {
  return error(400, 'missing_user_message', 'No user message found in messages');
}

// --- session identity: explicit header > OpenAI user field > anonymous ---
const sessionId = String(headers['x-session-id'] || body.user || 'anonymous');
const client = String(headers['x-client'] || 'unknown');

// Pass through supported sampling params when the client sends them
const llmParams = {};
for (const k of ['temperature', 'top_p', 'max_tokens', 'presence_penalty', 'frequency_penalty']) {
  if (body[k] !== undefined && body[k] !== null) llmParams[k] = body[k];
}

// Server-side memory is only meaningful when the client does NOT send full
// history (LobeChat always sends the full transcript, so it uses passthrough).
const needsHistory = messages.length <= 2 && lastUser === messages[messages.length - 1];

return [{ json: { ok: true, messages, model, upstream_model: upstreamModel, tools_enabled: alias.tools, llm_params: llmParams, session_id: sessionId, client, key_name: keyName, key_hash: keyHash, started_at: startedAt, needs_history: needsHistory } }];

/* Unify validation errors and upstream (HTTP) failures into one shape:
   { status, body: <OpenAI error envelope> } */
const item = $input.first().json;

if (item.__error) {
  return [{ json: { status: item.status, body: item.openai_error } }];
}

// HTTP Request node error output shape
const err = item.error || {};
const message = err.description || err.message || 'Upstream model call failed';
return [{ json: { status: 502, body: { error: { message, type: 'api_error', code: 'upstream_error' } } } }];

/* Merge persisted session history with the client's incoming messages.
   Used when the client relies on server-side memory (single new message). */
const meta = $('Parse & Validate').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.session_id === meta.session_id && (r.role === 'user' || r.role === 'assistant'));
const history = rows.reverse().slice(-20).map((r) => ({ role: r.role, content: String(r.content ?? '') }));
const messages = [...history, ...(meta.messages || [])];
const upstreamPayload = {
  model: meta.upstream_model,
  messages,
  stream: false,
  ...(meta.llm_params || {}),
};
return [{ json: { ...meta, messages, upstream_payload: upstreamPayload } }];

/* Assemble the upstream payload (DeepSeek is OpenAI-compatible) and carry
   gateway metadata forward. Round 0 arms BOTH tools (priority 5):
     - web_search  (SearXNG): public/current web information
     - kb_search   (pgvector): private knowledge base (ingested documents)
   The model decides whether to search; the loop lives in Check Response /
   Emit Tool Call Items / Execute Tool / Append Tool Results (max 2 rounds).
   A gateway directive system message enforces citation of kb sources. */
const item = $input.first().json;
const TOOLS = [{
  type: 'function',
  function: {
    name: 'web_search',
    description: 'Search the public web for current information, facts, news or documentation. Returns ranked results with title, url and snippet.',
    parameters: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'The search query' },
      },
      required: ['query'],
    },
  },
}, {
  type: 'function',
  function: {
    name: 'kb_search',
    description: 'Search the private knowledge base (ingested internal documents, notes and references). Use for questions about internal/content already added to the knowledge base. Returns passages with title, excerpt and relevance.',
    parameters: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'The search query, in the same language as the documents' },
        top_k: { type: 'integer', description: 'How many passages to return (1-10, default 6)' },
      },
      required: ['query'],
    },
  },
}];

const DIRECTIVE = 'Tool usage rules: (1) web_search searches the public web; kb_search searches the private knowledge base of ingested documents. Choose based on the question; you may use both. (2) When answering with kb_search results, ground the answer in the returned passages and cite them inline as [来源: <title>]. (3) If kb_search returns nothing relevant, say the knowledge base does not cover it instead of guessing.';

const withTools = item.tools_enabled !== false;
const messages = withTools ? [...item.messages, { role: 'system', content: DIRECTIVE }] : [...item.messages];
const upstreamPayload = {
  model: item.upstream_model,
  messages,
  stream: false,
  ...(withTools ? { tools: TOOLS } : {}),
  ...item.llm_params,
};
const tool_state = {
  round: 0,
  usage_acc: {
    prompt_tokens: 0,
    completion_tokens: 0,
    total_tokens: 0,
    prompt_cache_hit_tokens: 0,
    prompt_cache_miss_tokens: 0,
  },
};
return [{ json: { ...item, messages, upstream_payload: upstreamPayload, tool_state } }];

/* Wrap the final upstream chat completion into the OpenAI-compatible response.
   Usage is the accumulated total across agent-loop rounds; tool_rounds notes
   how many web_search rounds ran (0 = direct answer, no tools used). */
const item = $input.first().json;
const completion = item.choices?.[0] || {};
const acc = item.tool_state?.usage_acc || {};
const executionId = $execution.id;
return [{ json: {
  id: `chatcmpl-n8n-${executionId}`,
  object: 'chat.completion',
  created: Math.floor(Date.now() / 1000),
  model: $('Parse & Validate').first().json.model,
  choices: [
    {
      index: 0,
      message: { role: 'assistant', content: completion.message?.content ?? '' },
      finish_reason: completion.finish_reason ?? 'stop',
    },
  ],
  usage: {
    prompt_tokens: acc.prompt_tokens ?? item.usage?.prompt_tokens ?? 0,
    completion_tokens: acc.completion_tokens ?? item.usage?.completion_tokens ?? 0,
    total_tokens: acc.total_tokens ?? item.usage?.total_tokens ?? 0,
  },
  tool_rounds: item.tool_state?.round ?? 0,
} }];

/* Build the chat_executions row for a successful completion, compute the
   request cost and accumulate it into the key's running total.

   Pricing (USD per 1M tokens) — update when DeepSeek revises prices:
     deepseek-chat:     input 0.27 (cache hit 0.07), output 1.10
     deepseek-reasoner: input 0.55 (cache hit 0.14), output 2.19 */
const meta = $('Parse & Validate').first().json;
const resp = $input.first().json;
const usage = resp.usage || {};
const PRICING = {
  'deepseek-chat': { input: 0.27, cache_hit: 0.07, output: 1.10 },
  'deepseek-reasoner': { input: 0.55, cache_hit: 0.14, output: 2.19 },
  'deepseek-v4-flash': { input: 0.28, cache_hit: 0.0056, output: 0.56 }, // CNY peak 2/0.04/4 per 1M @7.2
};
const price = PRICING[meta.upstream_model] || { input: 0, cache_hit: 0, output: 0 };
const hit = Number(usage.prompt_cache_hit_tokens ?? 0);
const miss = Number(usage.prompt_cache_miss_tokens ?? Math.max((Number(usage.prompt_tokens) || 0) - hit, 0));
const completion = Number(usage.completion_tokens ?? 0);
const cost = Math.round(((hit / 1e6) * price.cache_hit + (miss / 1e6) * price.input + (completion / 1e6) * price.output) * 1e6) / 1e6;

// Accumulate into the key's running total. Fire-and-forget: bookkeeping
// happens after the response was already sent, a failure here must not
// affect anything the client sees. Fresh-read-then-add keeps concurrent
// requests from clobbering each other's amounts (personal-scale races are
// still possible; the stats API aggregates from exec rows as source of truth).
if (meta.key_hash) {
  try {
    const headers = { 'X-N8N-API-KEY': $env.N8N_API_KEY };
    const api = (method, path, qs, payload) => this.helpers.httpRequest({ method, url: 'http://localhost:5678/api/v1' + path, headers, qs, body: payload });
    const tables = await api('GET', '/data-tables', { limit: 100 });
    const gt = (tables.data || []).find((t) => t.name === 'gateway_keys');
    if (gt) {
      const idFilterObj = { type: 'and', filters: [{ columnName: 'key_hash', condition: 'eq', value: meta.key_hash }] };
      const cur = await api('GET', '/data-tables/' + gt.id + '/rows', { limit: 1, filter: JSON.stringify(idFilterObj) });
      const row = (cur.data || [])[0];
      if (row) {
        const r6 = (x) => Math.round(x * 1e6) / 1e6;
        const total = r6(Number(row.total_cost || 0) + cost);
        const nowMs = Date.now();
        let s24 = Number(row.spend_24h || 0);
        let at24 = Date.parse(row.spend_24h_at || '') || 0;
        if (nowMs - at24 > 24 * 3600 * 1000) { s24 = 0; at24 = nowMs; }
        let s30 = Number(row.spend_30d || 0);
        let at30 = Date.parse(row.spend_30d_at || '') || 0;
        if (nowMs - at30 > 30 * 24 * 3600 * 1000) { s30 = 0; at30 = nowMs; }
        await api('PATCH', '/data-tables/' + gt.id + '/rows/update', null, { filter: idFilterObj, data: {
          total_cost: total,
          spend_24h: r6(s24 + cost),
          spend_24h_at: new Date(at24).toISOString(),
          spend_30d: r6(s30 + cost),
          spend_30d_at: new Date(at30).toISOString(),
        } });
      }
    }
  } catch (e) {
    // best-effort bookkeeping
  }
}

return [{ json: {
  execution_id: String($execution.id),
  session_id: meta.session_id,
  model: meta.model,
  client: meta.client,
  key_name: meta.key_name || '',
  status: 'success',
  error_code: '',
  error_message: '',
  latency_ms: Date.now() - meta.started_at,
  prompt_tokens: usage.prompt_tokens ?? 0,
  completion_tokens: usage.completion_tokens ?? 0,
  total_tokens: usage.total_tokens ?? 0,
  cost_usd: cost,
} }];

/* Persist the turn transcript (user + assistant) for session memory.
   Runs on BOTH the success and error paths (after Insert Exec Row); on the
   error path Prep Success Log never ran, so the message rows are skipped. */
const meta = $('Parse & Validate').first().json;
let success = null;
try { success = $('Prep Success Log').first().json; } catch (e) { success = null; }
if (!success) return [];
const resp = $('Format OpenAI Response').first().json;
const userMsg = [...(meta.messages || [])].reverse().find((m) => m.role === 'user');
const rows = [
  { session_id: meta.session_id, role: 'user', content: userMsg?.content ?? '', model: meta.model, client: meta.client, key_name: meta.key_name || '', cost_usd: 0 },
  { session_id: meta.session_id, role: 'assistant', content: resp.choices?.[0]?.message?.content ?? '', model: meta.model, client: meta.client, key_name: meta.key_name || '', cost_usd: success.cost_usd ?? 0 },
];
return rows.map((json) => ({ json }));

/* Build the chat_executions row for a failed request/completion. */
const item = $input.first().json;
let meta = {};
try { meta = $('Parse & Validate').first().json || {}; } catch (e) { meta = {}; }
return [{ json: {
  execution_id: String($execution.id),
  session_id: meta.session_id || 'unknown',
  model: meta.model || 'unknown',
  client: meta.client || 'unknown',
  key_name: meta.key_name || '',
  status: 'error',
  error_code: item.body?.error?.code || 'unknown_error',
  error_message: String(item.body?.error?.message || '').slice(0, 500),
  latency_ms: meta.started_at ? Date.now() - meta.started_at : 0,
  prompt_tokens: 0,
  completion_tokens: 0,
  total_tokens: 0,
  cost_usd: 0,
} }];

/* Inspect the upstream response: accumulate usage across agent-loop rounds,
   detect tool_calls, and decide whether the loop continues (hard cap: 2 tool
   rounds — after that the follow-up request omits tools entirely, which
   guarantees termination). */
const item = $input.first().json; // DeepSeek response

// state of the request that produced this response
let prev_payload, tool_state;
try {
  ({ upstream_payload: prev_payload, tool_state } = $('Append Tool Results').first().json);
} catch {
  ({ upstream_payload: prev_payload, tool_state } = $('Build Upstream Payload').first().json);
}

const u = item.usage || {};
const acc = {
  prompt_tokens: (tool_state.usage_acc.prompt_tokens || 0) + (u.prompt_tokens || 0),
  completion_tokens: (tool_state.usage_acc.completion_tokens || 0) + (u.completion_tokens || 0),
  total_tokens: (tool_state.usage_acc.total_tokens || 0) + (u.total_tokens || 0),
  prompt_cache_hit_tokens: (tool_state.usage_acc.prompt_cache_hit_tokens || 0) + (u.prompt_cache_hit_tokens || 0),
  prompt_cache_miss_tokens: (tool_state.usage_acc.prompt_cache_miss_tokens || 0) + (u.prompt_cache_miss_tokens || 0),
};
const msg = item.choices?.[0]?.message || {};
const calls = Array.isArray(msg.tool_calls) ? msg.tool_calls : [];
const round = tool_state.round || 0;
const hasToolCalls = item.choices?.[0]?.finish_reason === 'tool_calls' && calls.length > 0 && round < 2;

if (!hasToolCalls) {
  return [{ json: { ...item, tool_state: { ...tool_state, usage_acc: acc }, has_tool_calls: false } }];
}

// build the assistant tool_calls message once for the follow-up request
const assistantMsg = { role: 'assistant', content: msg.content ?? null, tool_calls: calls };
const messages_base = [...(prev_payload.messages || []), assistantMsg];
const parsed = calls.map((c) => {
  let args = {};
  try {
    args = JSON.parse(c.function?.arguments || '{}') || {};
  } catch (e) {
    args = {};
  }
  return { tool_call_id: c.id, tool_name: c.function?.name || 'unknown', args };
});
return [{ json: {
  has_tool_calls: true,
  tool_state: { round: round + 1, usage_acc: acc },
  messages_base,
  model: prev_payload.model,
  llm_params: prev_payload.llm_params || {},
  tool_calls: parsed,
} }];

/* Split the parsed tool calls into one item each so each tool executes on its
   own. Every item carries the full loop state for Append Tool Results. */
const item = $input.first().json;
const calls = item.tool_calls || [];
if (!calls.length) return [];
const { tool_calls, ...rest } = item;
return calls.map((c) => ({ json: { ...rest, tool_call_id: c.tool_call_id, tool_name: c.tool_name, args: c.args || {} } }));

/* Execute each requested tool call and attach the result to the item.
     web_search -> SearXNG JSON API
     kb_search  -> DashScope query embedding + pgvector ANN over kb_chunks
   Failures become .result.error so the model can recover via the tool
   message instead of the workflow failing. */
const items = $input.all().map((i) => i.json);
const out = [];

for (const it of items) {
  let result;
  try {
    if (it.tool_name === 'web_search') {
      const q = String((it.args && it.args.query) || it.query || '').trim();
      if (!q) throw new Error('web_search was called without a query');
      const res = await this.helpers.httpRequest({
        method: 'GET',
        url: 'http://searxng:8080/search',
        qs: { q, format: 'json' },
        headers: { Accept: 'application/json' },
        timeout: 20000,
      });
      result = {
        type: 'web',
        results: (res.results || []).slice(0, 5).map((r) => ({
          title: r.title,
          url: r.url,
          snippet: (r.content || '').slice(0, 300),
        })),
      };
    } else if (it.tool_name === 'kb_search') {
      if (!($env.DASHSCOPE_API_KEY || '').trim()) {
        throw new Error('knowledge base is not configured (DASHSCOPE_API_KEY missing)');
      }
      const kbq = String((it.args && it.args.query) || it.query || '').trim();
      if (!kbq) throw new Error('kb_search was called without a query');
      const emb = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://dashscope.aliyuncs.com/api/v1/services/embeddings/text-embedding/text-embedding',
        headers: { Authorization: 'Bearer ' + $env.DASHSCOPE_API_KEY, 'Content-Type': 'application/json' },
        body: {
          model: 'qwen3.7-text-embedding',
          input: { texts: [kbq] },
          parameters: {
            dimension: 1024,
            text_type: 'query',
            output_type: 'dense',
            instruct: 'Given a user question about internal documents, retrieve the most relevant passages',
          },
        },
      });
      const vec = emb.output.embeddings[0].embedding;
      const { Client } = require('pg');
      const pg = new Client({
        host: $env.DB_POSTGRESDB_HOST || 'postgres',
        port: Number($env.DB_POSTGRESDB_PORT || 5432),
        database: $env.DB_POSTGRESDB_DATABASE || 'n8n',
        user: $env.DB_POSTGRESDB_USER || 'n8n',
        password: $env.DB_POSTGRESDB_PASSWORD,
      });
      await pg.connect();
      try {
        const k = Math.min(Math.max(Number(it.args && it.args.top_k) || 6, 1), 10);
        const q = await pg.query(
          `SELECT c.content, c.seq, d.title, 1 - (c.embedding <=> $1::vector) AS score
             FROM kb_chunks c JOIN kb_documents d ON d.doc_id = c.doc_id
            WHERE d.status = 'active'
            ORDER BY c.embedding <=> $1::vector LIMIT $2`,
          ['[' + vec.join(',') + ']', k]
        );
        result = {
          type: 'kb',
          results: q.rows.map((r) => ({
            title: r.title,
            seq: r.seq,
            excerpt: String(r.content).slice(0, 600),
            score: Math.round(Number(r.score) * 1000) / 1000,
          })),
        };
      } finally {
        await pg.end();
      }
    } else {
      result = { type: 'unknown', error: 'unknown tool: ' + it.tool_name };
    }
  } catch (e) {
    result = { error: String(e && e.message ? e.message : e).slice(0, 200) };
  }
  const { tool_calls, ...rest } = it;
  out.push({ json: { ...rest, result } });
}
return out;

/* Aggregate tool results into tool messages and build the next upstream
   payload. After MAX_ROUNDS the follow-up request omits tools entirely,
   forcing a final answer. Tool failures become error tool messages so the
   model can answer without that tool instead of the workflow failing. */
const items = $input.all().map((i) => i.json);
const MAX_ROUNDS = 2;

const TOOLS = [{
  type: 'function',
  function: {
    name: 'web_search',
    description: 'Search the public web for current information, facts, news or documentation. Returns ranked results with title, url and snippet.',
    parameters: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'The search query' },
      },
      required: ['query'],
    },
  },
}, {
  type: 'function',
  function: {
    name: 'kb_search',
    description: 'Search the private knowledge base (ingested internal documents, notes and references). Use for questions about internal/content already added to the knowledge base. Returns passages with title, excerpt and relevance.',
    parameters: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'The search query, in the same language as the documents' },
        top_k: { type: 'integer', description: 'How many passages to return (1-10, default 6)' },
      },
      required: ['query'],
    },
  },
}];

const first = items[0] || {};
const round = first.tool_state?.round ?? 1;

const toolMsgs = items.map((it) => {
  const res = it.result || {};
  let content;
  if (res.error) {
    content = JSON.stringify({ query: it.query, error: res.error });
  } else if (res.type === 'kb') {
    content = JSON.stringify({ query: it.query, sources: res.results });
  } else {
    content = JSON.stringify({ query: it.query, results: res.results });
  }
  return { role: 'tool', tool_call_id: it.tool_call_id, content };
});

const messages = [...(first.messages_base || []), ...toolMsgs];
const upstreamPayload = {
  model: first.model,
  messages,
  stream: false,
  ...(first.llm_params || {}),
};
if (round < MAX_ROUNDS) upstreamPayload.tools = TOOLS;

return [{ json: { upstream_payload: upstreamPayload, tool_state: first.tool_state } }];
